import * as vscode from 'vscode';

export function getWebviewContent(
  webview: vscode.Webview,
  extensionUri: vscode.Uri,
  initialMode: string = 'split'
): string {
  const scriptUri = webview.asWebviewUri(vscode.Uri.joinPath(extensionUri, 'dist', 'webview.js'));
  const styleUri = webview.asWebviewUri(vscode.Uri.joinPath(extensionUri, 'dist', 'webview.css'));
  const nonce = getNonce();

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src 'nonce-${nonce}'; img-src ${webview.cspSource} https: data:; font-src ${webview.cspSource};">
  <link rel="stylesheet" href="${styleUri}">
  <title>Jiny Markdown</title>
</head>
<body>
  <div id="app">
    <!-- Top Toolbar -->
    <header class="top-bar">
      <div class="brand-section">
        <span class="brand-icon">✨</span>
        <span>Jiny Markdown</span>
      </div>

      <!-- 3 View Modes Switcher -->
      <div class="mode-switcher" role="group" aria-label="View Mode">
        <button id="btn-mode-code" class="mode-btn ${initialMode === 'code' ? 'active' : ''}" title="Code Mode (Cmd+Alt+1 / Ctrl+Alt+1)">
          <span>📝</span> Code
        </button>
        <button id="btn-mode-split" class="mode-btn ${initialMode === 'split' ? 'active' : ''}" title="Split Mode (Cmd+Alt+2 / Ctrl+Alt+2)">
          <span>🌓</span> Split
        </button>
        <button id="btn-mode-preview" class="mode-btn ${initialMode === 'preview' ? 'active' : ''}" title="Typora Preview Mode (Cmd+Alt+3 / Ctrl+Alt+3)">
          <span>📖</span> Typora Preview
        </button>
      </div>

      <!-- Typora Quick Formatting Toolbar -->
      <div class="format-toolbar">
        <button class="format-btn" data-action="h1" title="Heading 1"><b>H1</b></button>
        <button class="format-btn" data-action="h2" title="Heading 2"><b>H2</b></button>
        <button class="format-btn" data-action="h3" title="Heading 3"><b>H3</b></button>
        <div class="toolbar-separator"></div>
        <button class="format-btn" data-action="bold" title="Bold (Ctrl+B / Cmd+B)"><b>B</b></button>
        <button class="format-btn" data-action="italic" title="Italic (Ctrl+I / Cmd+I)"><i>I</i></button>
        <button class="format-btn" data-action="strike" title="Strikethrough"><s>S</s></button>
        <div class="toolbar-separator"></div>
        <button class="format-btn" data-action="code" title="Inline Code"><code>&lt;&gt;</code></button>
        <button class="format-btn" data-action="codeblock" title="Code Block">&lt;/&gt;</button>
        <button class="format-btn" data-action="quote" title="Blockquote">❝</button>
        <div class="toolbar-separator"></div>
        <button class="format-btn" data-action="ul" title="Bullet List">• ≡</button>
        <button class="format-btn" data-action="ol" title="Numbered List">1. ≡</button>
        <button class="format-btn" data-action="task" title="Task List">☑</button>
        <button class="format-btn" data-action="table" title="Table">▦</button>
        <button class="format-btn" data-action="link" title="Link">🔗</button>
        <button class="format-btn" data-action="hr" title="Horizontal Rule">──</button>
      </div>

      <!-- Document Stats -->
      <div class="status-badge">
        <span id="status-stats">0 lines · 0 words</span>
      </div>
    </header>

    <!-- Workspace -->
    <main id="workspace" class="editor-workspace mode-${initialMode}">
      <!-- Code Pane -->
      <section class="code-pane">
        <div class="code-container">
          <div id="code-gutter" class="code-gutter"></div>
          <textarea id="code-textarea" class="code-textarea" spellcheck="false" placeholder="Write markdown here..."></textarea>
        </div>
      </section>

      <!-- Preview Pane (Pure White Background #ffffff, Line Numbers Gutter, Typora Live Edit) -->
      <section class="preview-pane">
        <div id="preview-scroll" class="preview-scroll-container">
          <!-- Line Numbers Gutter in Preview -->
          <div id="preview-gutter" class="preview-gutter"></div>
          <!-- Editable Markdown Document -->
          <article id="preview-content" class="preview-content" contenteditable="true" spellcheck="false" placeholder="Typora preview..."></article>
        </div>
      </section>
    </main>
  </div>

  <script nonce="${nonce}" src="${scriptUri}"></script>
</body>
</html>`;
}

function getNonce(): string {
  let text = '';
  const possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for (let i = 0; i < 32; i++) {
    text += possible.charAt(Math.floor(Math.random() * possible.length));
  }
  return text;
}
